"use client";
import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { 
  Trash2, Plus, Layout, Loader2, Users, 
  MessageSquare, Activity, ShieldAlert, Zap 
} from "lucide-react";

export default function AdminDashboard() {
  const { data: session } = useSession();
  const [data, setData] = useState<any>(null);
  const [newColumn, setNewColumn] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/admin/stats")
      .then((res) => res.json())
      .then((resData) => {
        setData(resData);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  const deleteUser = async (id: string) => {
    if (!confirm("⚠️ DİKKAT: Bu kullanıcıyı ve tüm verilerini kalıcı olarak silmek istediğinize emin misiniz?")) return;
    const res = await fetch(`/api/admin/users/${id}`, { method: "DELETE" });
    if (res.ok) {
      setData({ ...data, stats: data.stats.filter((u: any) => u.id !== id) });
    }
  };

  // Yükleme Ekranı (Cyberpunk Loading)
  if (loading || !data) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] gap-6">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-fuchsia-500/20 border-t-fuchsia-500 rounded-full animate-spin"></div>
          <Zap className="absolute inset-0 m-auto text-teal-400 animate-pulse" size={32} />
        </div>
        <p className="text-teal-400 font-black tracking-[0.5em] uppercase text-sm animate-pulse">
          Sistem Verileri Senkronize Ediliyor...
        </p>
      </div>
    );
  }

  const stats = data?.stats || [];
  const messages = data?.messages || [];

  return (
    <div className="space-y-12 pb-24 animate-in fade-in slide-in-from-bottom-4 duration-1000">
      
      {/* ÜST BİLGİ KARTLARI */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard icon={<Users className="text-fuchsia-500" />} label="Toplam Kullanıcı" value={stats.length} />
        <StatCard icon={<MessageSquare className="text-teal-400" />} label="Yeni Mesajlar" value={messages.length} />
        <StatCard icon={<Activity className="text-yellow-400" />} label="Sistem Durumu" value="Aktif" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        
        {/* SOL KOLON: KULLANICI YÖNETİMİ */}
        <div className="lg:col-span-2 space-y-8">
          <section className="bg-[#0E153A]/80 border border-teal-400/10 rounded-[3rem] overflow-hidden backdrop-blur-xl shadow-2xl">
            <div className="p-8 border-b border-teal-400/10 flex justify-between items-center bg-teal-400/5">
              <h2 className="text-xl font-black text-white uppercase tracking-tighter italic flex items-center gap-3">
                <Users size={24} className="text-fuchsia-500" /> Kullanıcı Veritabanı
              </h2>
              <span className="text-[10px] bg-fuchsia-500/20 text-fuchsia-400 px-3 py-1 rounded-full font-bold uppercase tracking-widest">Canlı İzleme</span>
            </div>
            
            <div className="divide-y divide-teal-400/5">
              {stats.map((user: any) => (
                <div key={user.id} className="p-8 flex items-center justify-between hover:bg-white/[0.02] transition-all group">
                  <div className="flex items-center gap-6">
                    <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-teal-400/20 to-fuchsia-500/20 flex items-center justify-center border border-white/10 text-white font-black text-xl">
                      {user.name?.[0] || "U"}
                    </div>
                    <div>
                      <h3 className="text-white font-bold text-lg group-hover:text-fuchsia-400 transition-colors">{user.name || "Anonim"}</h3>
                      <p className="text-xs text-teal-500/40 font-mono">{user.email}</p>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-8">
                    <div className="hidden md:block text-right">
                      <p className="text-[10px] text-teal-500/30 uppercase font-black mb-1">Verimlilik</p>
                      <div className="w-32 h-1.5 bg-black/40 rounded-full overflow-hidden border border-white/5">
                        <div className="h-full bg-fuchsia-500" style={{ width: `${user.percentage}%` }} />
                      </div>
                    </div>
                    <span className="text-fuchsia-400 font-black italic text-xl">{user.percentage}%</span>
                    <button 
                      onClick={() => deleteUser(user.id)}
                      className="p-4 bg-red-500/10 text-red-500 rounded-2xl hover:bg-red-500 hover:text-white transition-all transform hover:rotate-12 active:scale-90"
                    >
                      <Trash2 size={20} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </section>
        </div>

        {/* SAĞ KOLON: KONTROL PANELİ & MESAJLAR */}
        <div className="space-y-8">
          {/* İŞ AKIŞI EKLEME */}
          <section className="bg-gradient-to-br from-[#0E153A] to-[#1A1F45] border border-fuchsia-500/20 p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-10"><Layout size={80} /></div>
            <h3 className="text-white font-black uppercase italic mb-6 flex items-center gap-2">
              <Plus size={20} className="text-fuchsia-500" /> Süreç Ekle
            </h3>
            <div className="space-y-4">
              <input 
                value={newColumn}
                onChange={(e) => setNewColumn(e.target.value)}
                placeholder="Örn: Review, Retro..."
                className="w-full bg-black/40 border border-teal-400/10 p-4 rounded-2xl text-white outline-none focus:border-fuchsia-500 transition-all placeholder:text-white/10"
              />
              <button 
                onClick={() => alert("Aşama eklendi!")}
                className="w-full bg-fuchsia-600 p-4 rounded-2xl text-white font-black uppercase tracking-widest hover:bg-fuchsia-500 shadow-lg shadow-fuchsia-500/20 transition-all active:scale-95"
              >
                Sisteme Enjekte Et
              </button>
            </div>
          </section>

          {/* MESAJLAR */}
          <section className="bg-[#0E153A]/50 border border-teal-400/10 rounded-[2.5rem] p-8">
            <h3 className="text-teal-400 font-black uppercase text-xs tracking-[0.3em] mb-6">İletişim Hattı</h3>
            <div className="space-y-6">
              {messages.map((m: any) => (
                <div key={m.id} className="relative pl-6 border-l-2 border-fuchsia-500/30 hover:border-fuchsia-500 transition-colors">
                  <p className="text-white font-bold text-sm mb-1">{m.name}</p>
                  <p className="text-white/50 text-xs leading-relaxed line-clamp-2">{m.message}</p>
                </div>
              ))}
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

function StatCard({ icon, label, value }: any) {
  return (
    <div className="bg-[#0E153A]/80 border border-teal-400/10 p-8 rounded-[2.5rem] flex items-center gap-6 hover:border-teal-400/30 transition-all group shadow-xl">
      <div className="w-14 h-14 rounded-2xl bg-black/20 flex items-center justify-center group-hover:scale-110 transition-transform">
        {icon}
      </div>
      <div>
        <p className="text-[10px] text-teal-500/40 uppercase font-black tracking-widest">{label}</p>
        <p className="text-2xl text-white font-black">{value}</p>
      </div>
    </div>
  );
}